<?php
declare(strict_types=1);
namespace QualitySystem\Tests;
use PDO;use PHPUnit\Framework\Attributes\Group;use PHPUnit\Framework\TestCase;use QualitySystem\Repositories\TaskRepository;use QualitySystem\Security\PermissionMatrix;
final class TaskAuthorizationTest extends TestCase
{
    private PDO $pdo;private int $owner;private int $other;private int $program;private bool $createdProgram=false;private array $taskIds=[];
    protected function setUp():void{$c=require 'C:\\quality_system_config\\database.php';$this->pdo=new PDO("mysql:host={$c['host']};port={$c['port']};dbname={$c['name']};charset=utf8mb4",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$suffix=bin2hex(random_bytes(5));$s=$this->pdo->prepare("INSERT INTO users(full_name,email,password_hash,role,status) VALUES(?,?,?,?, 'Active')");$s->execute(['Scope Owner',"scope-owner-$suffix@invalid.test",password_hash($suffix,PASSWORD_DEFAULT),'Faculty']);$this->owner=(int)$this->pdo->lastInsertId();$s->execute(['Scope Other',"scope-other-$suffix@invalid.test",password_hash($suffix,PASSWORD_DEFAULT),'Faculty']);$this->other=(int)$this->pdo->lastInsertId();$p=$this->pdo->query('SELECT id FROM program_specifications ORDER BY id LIMIT 1')->fetchColumn();if(!$p){$s=$this->pdo->prepare('INSERT INTO program_specifications(specification_title,program_name) VALUES(?,?)');$s->execute(["Scope Test $suffix","Scope Test $suffix"]);$p=$this->pdo->lastInsertId();$this->createdProgram=true;}$this->program=(int)$p;$this->pdo->prepare("INSERT INTO user_program_access(user_id,program_specification_id,access_level) VALUES(?,?,'Member')")->execute([$this->owner,$this->program]);$insert=$this->pdo->prepare("INSERT INTO tasks(task_title,assigned_user_id,program_specification_id,created_by_user_id,status,priority) VALUES(?,?,?,?, 'Pending','Medium')");foreach([['Assigned',$this->owner,null,$this->other],['Program',null,$this->program,$this->other],['Foreign',$this->other,null,$this->other]] as $row){$insert->execute($row);$this->taskIds[]=(int)$this->pdo->lastInsertId();}}
    protected function tearDown():void{if(!isset($this->pdo))return;if($this->taskIds){$q=implode(',',array_fill(0,count($this->taskIds),'?'));$this->pdo->prepare("DELETE FROM tasks WHERE id IN ($q)")->execute($this->taskIds);}$this->pdo->prepare('DELETE FROM user_program_access WHERE user_id IN (?,?)')->execute([$this->owner,$this->other]);$this->pdo->prepare('DELETE FROM users WHERE id IN (?,?)')->execute([$this->owner,$this->other]);if($this->createdProgram)$this->pdo->prepare('DELETE FROM program_specifications WHERE id=?')->execute([$this->program]);}
    #[Group('database')]
    public function testFacultyCannotReadAnotherUsersUnscopedTask():void{$repo=new TaskRepository($this->pdo);self::assertNotNull($repo->findScoped($this->taskIds[0],'Faculty',$this->owner));self::assertNotNull($repo->findScoped($this->taskIds[1],'Faculty',$this->owner));self::assertNull($repo->findScoped($this->taskIds[2],'Faculty',$this->owner));}
    public function testRoleActionMatrix():void{self::assertTrue(PermissionMatrix::allows('Reviewer','tasks','view'));self::assertFalse(PermissionMatrix::allows('Reviewer','tasks','update'));self::assertFalse(PermissionMatrix::allows('Faculty','tasks','delete'));self::assertTrue(PermissionMatrix::allows('Quality Coordinator','tasks','delete'));}
}
